import{_ as r,l,o as e,c as p,v as t,p as n,x as o,d as s,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"机台价格与折旧","description":"","frontmatter":{"title":"机台价格与折旧","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/tool-price-depreciation.md","filePath":"litho/tool-price-depreciation.md","lastUpdated":1789023840000}'),c={name:"litho/tool-price-depreciation.md"};function E(_,a,B,u,A,m){const i=l("Mermaid");return e(),p("div",null,[a[1]||(a[1]=t('<h1 id="机台价格与折旧" tabindex="-1">机台价格与折旧 <a class="header-anchor" href="#机台价格与折旧" aria-label="Permalink to &quot;机台价格与折旧&quot;">​</a></h1><div class="epigraph"><p>扫描机的小时成本是买价按年折旧再除以有效 wph；EUV 与高 NA 把分子抬高，剂量把分母压低。</p><footer>—— 对照 ASML FY2024：净销售 €28.3B；EUV 系统销售 €8.3B / 44 台（含 High-NA）；DUV €12.8B / 374 台；Installed Base €6.5B。年报给销量与销售额，不给可抄的价目表</footer></div><p><a href="/litho/euv-vs-multipattern-cost-crossover">上一课</a>用模块成本比较路径。缺口是模块里最大的资本项。本课钉机台价格与折旧。折旧如何在厂级变成瓶颈机台数量，留给[下一课](/litho/capacity-planning-bottleneck）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>光刻机台（尤其 EUV、高 NA）是晶圆厂最贵的单机之一。会计上折旧年限（常见五到七年量级的产业讨论，非本课税法意见）把买价摊成年度成本，再按可用小时与 wph 摊到晶圆。维护、光源耗材、服务合同是现金，不一定走同一折旧科目，但进小时成本。浸没机单价低、wph 高，多重次数把有效层成本拉回。</p><p>缺口是<strong>资本回收</strong>，不是光学。ASML 年报给的是销量与销售额：2024 年 EUV 系统 €8.3B、确认收入 44 台（NXE 与 EXE），DUV €12.8B、374 台。这只是平均确认收入量级，混有机型与升级，<strong>不是</strong>目录价。服务与升级走 Installed Base（2024 年 €6.5B），与折旧并列进小时成本。</p><h3 id="有效-wph" tabindex="-1">有效 wph <a class="header-anchor" href="#有效-wph" aria-label="Permalink to &quot;有效 wph&quot;">​</a></h3><p>可用性、setup、剂量、pellicle、计量插入，把铭牌 wph 打成有效 wph。折旧分母是有效，不是铭牌。</p><p><span class="marginnote">高 NA 半场可能让大 die 的有效场数下降，分母再变。经济课与拼接课必须一起读。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>小时成本 ≈ (折旧 + 服务 + 耗材) / 有效小时。层成本再除有效 wph 乘过机次数。产能规划用同一套分母。与掩模：写模机也是折旧对象，进掩模摊销。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>固定成本高的机台必须高利用率，否则小时爆炸——这会压迫排产把非临界层塞进浸没，把 EUV 留给交叉后的层。利用率与混跑策略因此是财务约束，不只是工程偏好。</p>',13)),(e(),n(d,null,{default:o(()=>[h(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRICE%5B%22%E4%B9%B0%E4%BB%B7%22%5D%20--%3E%20DEP%5B%22%E5%B9%B4%E6%8A%98%E6%97%A7%22%5D%0A%20%20DEP%20--%3E%20HR%5B%22%E5%B0%8F%E6%97%B6%E6%88%90%E6%9C%AC%22%5D%0A%20%20AVAIL%5B%22%E5%8F%AF%E7%94%A8%E5%B0%8F%E6%97%B6%20%C3%97%20%E6%9C%89%E6%95%88%20wph%22%5D%20--%3E%20HR%0A%20%20HR%20--%3E%20LAYER%5B%22%E5%B1%82%E6%88%90%E6%9C%AC%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不提供投资建议，不给具体标价。折旧年限因公司而异。机台价格不含厂房。</p><p>后课默认：小时成本由折旧与有效 wph 决定；下一课用它来数需要几台、瓶颈在哪。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>层资本成本来自折旧除以有效 wph，不是铭牌。</li><li>高单价机必须高利用率，从而塑造混跑。</li><li>不把传闻标价写进账。</li><li>出处：ASML Q4/FY 2024 新闻稿与 IR 演示（2025-01-29）；半导体设备折旧的产业通称。不把 €8.3B/44 写成标价。</li></ul>',5))])}const b=r(c,[["render",E]]);export{P as __pageData,b as default};
